(()=>{const KEY='lkuni.language';const dictionaries={ru:{language:'RU',logout:'Выйти'},en:{language:'EN',logout:'Sign out'}};function current(){return localStorage.getItem(KEY)||'ru'}function accessToken(){return localStorage.getItem('lkuni.accessToken')||sessionStorage.getItem('lkuni.accessToken')||''}async function persistAuthenticatedLanguage(language){const token=accessToken();if(!token)return;try{await fetch('/api/v1/profile/settings',{method:'PATCH',headers:{'content-type':'application/json','authorization':'Bearer '+token},body:JSON.stringify({language})})}catch{}}function set(lang,source='programmatic'){const next=lang==='en'?'en':'ru';localStorage.setItem(KEY,next);document.documentElement.lang=next;document.dispatchEvent(new CustomEvent('lkuni:language',{detail:{language:next,source}}));if(source==='user')persistAuthenticatedLanguage(next);return next}function toggle(){return set(current()==='ru'?'en':'ru','user')}function text(key,lang=current()){return dictionaries[lang]?.[key]||dictionaries.ru[key]||key}function renderButton(button){if(!button)return;button.textContent=current()==='ru'?'RU · EN':'EN · RU';button.setAttribute('aria-label',current()==='ru'?'Switch interface to English':'Переключить интерфейс на русский')}function bindButton(button){if(!button)return;if(button.dataset.lkuniI18nBound!=='1'){button.dataset.lkuniI18nBound='1';button.addEventListener('click',()=>toggle());document.addEventListener('lkuni:language',()=>renderButton(button))}renderButton(button)}window.LkUniI18n={current,set,toggle,text,bindButton};document.documentElement.lang=current()})();